"use client";

import {
  useRef,
  useMemo,
  useCallback,
  useState,
  useEffect,
  useLayoutEffect,
} from "react";
import { createPortal } from "react-dom";
import {
  addDays,
  addWeeks,
  isWeekend,
  startOfDay,
  startOfMonth,
} from "date-fns";

import { cn } from "@/lib/utils";
import { useMonthEventDrag } from "@/hooks/use-month-event-drag";
import { useMonthEventResize } from "@/hooks/use-month-event-resize";
import { useVerticalScroll } from "@/hooks/use-vertical-scroll";
import { useEventKeyboard } from "@/hooks/use-event-keyboard";
import {
  MONTH_VIEW_ROWS,
  generateConsecutiveWeeks,
  generateWeekRow,
} from "@/lib/event-utils";
import { isMultiDayEvent } from "@/lib/event-utils";
import { MonthViewGrid } from "./month-view-grid";
import { MonthViewEventBar } from "./month-view-event-bar";
import { MonthViewEventItem } from "./month-view-event-item";
import { EventContextMenu } from "./event-context-menu";
import {
  CalendarPopoverBoundaryProvider,
  isEventInsideCalendarPopover,
} from "./calendar-popover-context";
import { CalendarLoadingBar } from "./calendar-loading-bar";
import {
  useCalendar,
  useCalendarConfig,
  useCalendarViewSync,
} from "./calendar-provider";
import type { CalendarEvent } from "./calendar-types";
import type { MonthViewProps } from "./week-view-types";
import type { MonthWeekRow } from "@/lib/event-utils";

/** Base buffer rows on each side (extends dynamically with scroll distance) */
const BUFFER_ROWS = 2;

interface ContextMenuState {
  x: number;
  y: number;
  event: CalendarEvent;
}

/**
 * Month grid calendar. Date, events, selection and view settings come from
 * the surrounding CalendarProvider.
 */
export function MonthView({
  showEventPopover = true,
  onEventPopoverExpand,
  className,
}: MonthViewProps) {
  const {
    view,
    currentDate,
    events,
    viewSettings,
    weekStartsOn,
    selectedEvent,
    selectEvent,
    clearSelection,
    updateEvent,
    goToDate,
    showDay,
    loading,
  } = useCalendar();
  const { locale } = useCalendarConfig();
  const { reportView, reportDisplayMonth, closeEventPopover } =
    useCalendarViewSync();
  /**
   * Whether the provider navigates by month. False for the commit before it
   * adopts this view (on mount, or right after a switch it doesn't follow).
   */
  const isProviderInSync = view === "month";
  const boundaryRef = useRef<HTMLDivElement | null>(null);
  const headerRef = useRef<HTMLDivElement | null>(null);
  const gridRef = useRef<HTMLDivElement | null>(null);

  const selectedEventId = selectedEvent?.id;
  const { showWeekends, showWeekNumbers } = viewSettings;

  const [contextMenu, setContextMenu] = useState<ContextMenuState | null>(null);

  const weekRows = useMemo(
    () =>
      generateConsecutiveWeeks(
        currentDate,
        MONTH_VIEW_ROWS,
        weekStartsOn,
        locale,
      ),
    [currentDate, weekStartsOn, locale],
  );

  // Derive the display month from the center of the visible rows.
  // This determines the header title and adjacent-month dimming.
  const displayMonth = useMemo(() => {
    const middleRow = weekRows[Math.floor(weekRows.length / 2)];
    if (!middleRow) return startOfMonth(currentDate);
    // Use the Thursday of the middle row (ISO convention for determining the week's month)
    const midDate = middleRow.days[Math.min(4, middleRow.days.length - 1)].date;
    return startOfMonth(midDate);
  }, [weekRows, currentDate]);

  // Tell the provider which view is on screen. `reportView` changes with the
  // provider's state, so this also re-checks after every switch. A layout
  // effect: the provider adopts month view before the first paint.
  useLayoutEffect(() => {
    reportView({ view: "month" });
  }, [reportView]);

  // Report the display month to the provider (header and sidebar sync). Not
  // while it is adopting this view: the date is about to change.
  useEffect(() => {
    if (!isProviderInSync) return;
    reportDisplayMonth(displayMonth);
  }, [isProviderInSync, displayMonth, reportDisplayMonth]);

  // Weekday columns in display order, starting on `weekStartsOn`, named in
  // the calendar's locale ("Sun", "Mon") like the rows' days
  const dayNames = useMemo(() => {
    const firstWeek = weekRows[0]?.days ?? [];
    const visibleDays = showWeekends
      ? firstWeek
      : firstWeek.filter((day) => !isWeekend(day.date));
    return visibleDays.map((day) => day.dayName);
  }, [weekRows, showWeekends]);

  const colCount = dayNames.length;
  const gridTemplateColumns = showWeekNumbers
    ? `2rem repeat(${colCount}, minmax(0, 1fr))`
    : `repeat(${colCount}, minmax(0, 1fr))`;

  const handleEventClick = useCallback(
    (event: CalendarEvent) => selectEvent(event.id),
    [selectEvent],
  );

  const { dragState, handleDragPointerDown } = useMonthEventDrag({
    gridRef,
    events,
    onEventChange: updateEvent,
    onEventClick: handleEventClick,
  });

  const { resizeState, handleResizePointerDown } = useMonthEventResize({
    gridRef,
    events,
    onEventChange: updateEvent,
  });

  const isDragging = dragState?.isDragging ?? false;
  const dragEventId = isDragging ? dragState?.eventId : undefined;
  const isResizing = resizeState?.isResizing ?? false;
  const resizeEventId = isResizing ? resizeState?.eventId : undefined;

  const scrollContainerRef = useRef<HTMLDivElement | null>(null);
  const visibleRowCount = weekRows.length;

  const [rowHeight, setRowHeight] = useState(0);

  // Measure row height from container
  useEffect(() => {
    const el = scrollContainerRef.current;
    if (!el || visibleRowCount === 0) return;
    const observer = new ResizeObserver(() => {
      setRowHeight(el.clientHeight / visibleRowCount);
    });
    observer.observe(el);
    return () => observer.disconnect();
  }, [visibleRowCount]);

  const scrollNavigatedRef = useRef(false);

  const handleScrollNavigate = useCallback(
    (rowsDelta: number) => {
      scrollNavigatedRef.current = true;
      const newDate = addWeeks(currentDate, rowsDelta);
      goToDate(newDate);
    },
    [currentDate, goToDate],
  );

  const { scrollOffset, slideOffset, isAnimating, triggerSlideAnimation } =
    useVerticalScroll({
      containerRef: scrollContainerRef,
      rowHeight,
      onNavigate: handleScrollNavigate,
      disabled: isDragging || isResizing,
    });

  // Detect external currentDate changes (button/keyboard nav) and trigger slide animation
  const prevDateRef = useRef(currentDate);
  const wasProviderInSyncRef = useRef(isProviderInSync);
  useEffect(() => {
    const wasProviderInSync = wasProviderInSyncRef.current;
    wasProviderInSyncRef.current = isProviderInSync;

    if (scrollNavigatedRef.current) {
      scrollNavigatedRef.current = false;
      prevDateRef.current = currentDate;
      return;
    }

    const prevDate = prevDateRef.current;
    prevDateRef.current = currentDate;

    if (prevDate.getTime() === currentDate.getTime()) return;
    // Dates set while the provider adopts this view (an undone switch, such
    // as "+N more" without a week view to open) are not navigation
    if (!wasProviderInSync || !isProviderInSync) return;

    // Calculate how many weeks changed
    const weeksDelta = Math.round(
      (currentDate.getTime() - prevDate.getTime()) / (7 * 24 * 60 * 60 * 1000),
    );

    if (weeksDelta !== 0) {
      triggerSlideAnimation(weeksDelta);
    }
  }, [currentDate, isProviderInSync, triggerSlideAnimation]);

  /** Whether a day is in one of the on-screen week rows */
  const isDayVisible = useCallback(
    (date: Date) => {
      const firstRow = weekRows[0];
      const lastRow = weekRows[weekRows.length - 1];
      if (!firstRow || !lastRow) return false;
      const first = startOfDay(firstRow.days[0].date);
      const afterLast = addDays(
        startOfDay(lastRow.days[lastRow.days.length - 1].date),
        1,
      );
      return date >= first && date < afterLast;
    },
    [weekRows],
  );

  /** Scrolls a row toward a day just off screen (keyboard moves go a week at most) */
  const revealDay = useCallback(
    (date: Date) => {
      const firstDay = weekRows[0]?.days[0]?.date ?? currentDate;
      goToDate(addWeeks(currentDate, date < firstDay ? -1 : 1));
    },
    [weekRows, currentDate, goToDate],
  );

  const handleEventKeyDown = useEventKeyboard({
    containerRef: boundaryRef,
    isDayVisible,
    revealDay,
  });

  // Symmetric buffer: extends in both directions (mirrors week view's dynamicBuffer)
  const extraScrollRows =
    rowHeight > 0 ? Math.ceil(Math.abs(scrollOffset) / rowHeight) : 0;
  const dynamicBuffer = BUFFER_ROWS + extraScrollRows;

  // Build buffered week rows: dynamicBuffer above + MONTH_VIEW_ROWS + dynamicBuffer below
  const bufferedWeekRows = useMemo(() => {
    if (weekRows.length === 0) return weekRows;
    const rows: MonthWeekRow[] = [];
    const firstDate = weekRows[0].days[0].date;
    for (let i = dynamicBuffer; i > 0; i--) {
      rows.push(generateWeekRow(addWeeks(firstDate, -i), weekStartsOn, locale));
    }
    rows.push(...weekRows);
    const lastDate = weekRows[weekRows.length - 1].days[0].date;
    for (let i = 1; i <= dynamicBuffer; i++) {
      rows.push(generateWeekRow(addWeeks(lastDate, i), weekStartsOn, locale));
    }
    return rows;
  }, [weekRows, dynamicBuffer, weekStartsOn, locale]);

  // Base offset hides the top buffer; scrollOffset + slideOffset shift within
  const baseTranslateY = -(dynamicBuffer * rowHeight);
  const transformY = baseTranslateY + scrollOffset + slideOffset;
  const scrollStyle: React.CSSProperties = {
    transform: `translateY(${transformY}px)`,
    transition: isAnimating ? "transform 200ms ease-out" : undefined,
  };

  // During resize, substitute the resized event's dates so the grid
  // recalculates layout in real-time (live preview with reflow).
  // Keep isAllDay true so the event stays rendered as a bar even when
  // resized down to a single day.
  const displayEvents = useMemo(() => {
    if (!isResizing || !resizeState) return events;
    return events.map((ev) =>
      ev.id === resizeState.eventId
        ? {
            ...ev,
            start: resizeState.currentStart,
            end: resizeState.currentEnd,
            isAllDay: true,
          }
        : ev,
    );
  }, [events, isResizing, resizeState]);

  const handleContextMenu = useCallback(
    (e: React.MouseEvent, event: CalendarEvent) => {
      e.preventDefault();
      setContextMenu({ x: e.clientX, y: e.clientY, event });
    },
    [],
  );

  const handleRootClick = useCallback(
    (e: React.MouseEvent<HTMLDivElement>) => {
      const target = e.target as HTMLElement;
      if (
        isEventInsideCalendarPopover(e) ||
        target.closest("button") ||
        target.closest("[role='button']")
      ) {
        return;
      }
      clearSelection();
    },
    [clearSelection],
  );

  return (
    <CalendarPopoverBoundaryProvider
      boundaryRef={boundaryRef}
      headerRef={headerRef}
      view="month"
    >
      <div
        ref={boundaryRef}
        className={cn("flex h-full flex-col overflow-hidden", className)}
        aria-busy={loading || undefined}
        onClick={handleRootClick}
        onKeyDown={handleEventKeyDown}
      >
        {/* Day-of-week header — right-aligned to match day number positions */}
        <div
          ref={headerRef}
          className="relative border-b border-border bg-background"
          style={{ display: "grid", gridTemplateColumns }}
        >
          {showWeekNumbers && (
            <div className="py-2 text-center text-[11px] text-muted-foreground">
              w
            </div>
          )}
          {dayNames.map((name) => (
            <div
              key={name}
              className="py-2 text-center text-[13px] text-muted-foreground"
            >
              {name}
            </div>
          ))}
          {loading && <CalendarLoadingBar />}
        </div>

        {/* Month grid — fills remaining space */}
        <div ref={scrollContainerRef} className="flex-1 overflow-hidden">
          <MonthViewGrid
            weekRows={bufferedWeekRows}
            events={displayEvents}
            currentMonth={displayMonth}
            showWeekNumbers={showWeekNumbers}
            showWeekends={showWeekends}
            onEventClick={handleEventClick}
            onContextMenu={handleContextMenu}
            onMoreClick={showDay}
            onDayNumberClick={showDay}
            onBackgroundClick={clearSelection}
            onDragPointerDown={handleDragPointerDown}
            onResizePointerDown={handleResizePointerDown}
            selectedEventId={selectedEventId}
            dragEventId={dragEventId}
            resizeEventId={resizeEventId}
            dragTargetDate={isDragging ? dragState?.targetDate : undefined}
            dragEvent={isDragging ? dragState?.event : undefined}
            showEventPopover={showEventPopover}
            onEventChange={updateEvent}
            onEventPopoverExpand={onEventPopoverExpand}
            onEventPopoverClose={closeEventPopover}
            visibleRowCount={visibleRowCount}
            visibleRowStart={dynamicBuffer}
            scrollStyle={scrollStyle}
            gridRef={gridRef}
          />
        </div>

        {/* Context menu */}
        {contextMenu && (
          <EventContextMenu
            event={contextMenu.event}
            position={{ x: contextMenu.x, y: contextMenu.y }}
            onClose={() => setContextMenu(null)}
            onEventChange={updateEvent}
          />
        )}

        {/* Floating drag copy — portaled to body, follows cursor */}
        {isDragging &&
          dragState &&
          createPortal(
            <div
              aria-hidden
              className="pointer-events-none fixed z-[9999] w-48 opacity-80 shadow-lg"
              style={{
                left: dragState.clientX - 96,
                top: dragState.clientY - 10,
              }}
            >
              {dragState.event.isAllDay || isMultiDayEvent(dragState.event) ? (
                <MonthViewEventBar
                  event={dragState.event}
                  colSpan={1}
                  roundedLeft
                  roundedRight
                  isDragging
                />
              ) : (
                <MonthViewEventItem event={dragState.event} isDragging />
              )}
            </div>,
            document.body,
          )}
      </div>
    </CalendarPopoverBoundaryProvider>
  );
}

"use client";

import { useRef, useState, useEffect, useMemo } from "react";
import { startOfDay } from "date-fns";
import { cn } from "@/lib/utils";
import type { CalendarEvent } from "./calendar-types";
import type { MonthWeekRow } from "@/lib/event-utils";
import { calculateMonthCellLayout, getMonthSlotCount } from "@/lib/event-utils";
import { MonthViewDayCell } from "./month-view-day-cell";

/** Default cell height in px before ResizeObserver measures the real height */
const DEFAULT_CELL_HEIGHT = 120;

export interface MonthViewGridProps {
  weekRows: MonthWeekRow[];
  events: CalendarEvent[];
  currentMonth: Date;
  showWeekNumbers?: boolean;
  showWeekends?: boolean;
  onEventClick?: (event: CalendarEvent) => void;
  onContextMenu?: (e: React.MouseEvent, event: CalendarEvent) => void;
  onMoreClick?: (date: Date) => void;
  onDayNumberClick?: (date: Date) => void;
  onBackgroundClick?: () => void;
  onDragPointerDown?: (
    e: React.PointerEvent<HTMLElement>,
    event: CalendarEvent,
  ) => void;
  onResizePointerDown?: (
    e: React.PointerEvent<HTMLElement>,
    event: CalendarEvent,
    edge: "left" | "right",
  ) => void;
  selectedEventId?: string;
  /** ID of the event currently being dragged (renders as ghost) */
  dragEventId?: string;
  /** ID of the event currently being resized (renders as selected) */
  resizeEventId?: string;
  /** Target date for drag placeholder */
  dragTargetDate?: Date;
  /** The event being dragged (for placeholder rendering) */
  dragEvent?: CalendarEvent;
  /** Whether the selected event shows its details popover */
  showEventPopover?: boolean;
  onEventChange?: (event: CalendarEvent) => void;
  /** Callback for the popover's expand button (hidden when absent) */
  onEventPopoverExpand?: () => void;
  /** Callback to close the popover (clears the selection) */
  /** Closes the given event's popover (clears it only while it is still selected) */
  onEventPopoverClose?: (eventId: string) => void;
  /** Number of rows visible in the viewport (for row height calculation) */
  visibleRowCount?: number;
  /** Index in `weekRows` of the first on-screen row (the rest are scroll buffer) */
  visibleRowStart?: number;
  /** CSS style for scroll transform */
  scrollStyle?: React.CSSProperties;
  /** Forwarded ref for the grid container (used by drag hook) */
  gridRef?: React.RefObject<HTMLDivElement | null>;
  className?: string;
}

export function MonthViewGrid({
  weekRows,
  events,
  currentMonth,
  showWeekNumbers = false,
  showWeekends = true,
  onEventClick,
  onContextMenu,
  onMoreClick,
  onDayNumberClick,
  onBackgroundClick,
  onDragPointerDown,
  onResizePointerDown,
  selectedEventId,
  dragEventId,
  resizeEventId,
  dragTargetDate,
  dragEvent,
  showEventPopover,
  onEventChange,
  onEventPopoverExpand,
  onEventPopoverClose,
  visibleRowCount,
  visibleRowStart = 0,
  scrollStyle,
  gridRef,
  className,
}: MonthViewGridProps) {
  const localRef = useRef<HTMLDivElement>(null);
  const containerRef = gridRef ?? localRef;

  const [cellHeight, setCellHeight] = useState(DEFAULT_CELL_HEIGHT);
  const rowCountForHeight = visibleRowCount ?? weekRows.length;

  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;

    const observer = new ResizeObserver(() => {
      if (rowCountForHeight === 0) return;
      setCellHeight(el.clientHeight / rowCountForHeight);
    });

    observer.observe(el);

    return () => {
      observer.disconnect();
    };
  }, [containerRef, rowCountForHeight]);

  const maxSlots = getMonthSlotCount(cellHeight);

  const cellLayouts = useMemo(
    () => calculateMonthCellLayout(weekRows, events, maxSlots),
    [weekRows, events, maxSlots],
  );

  const columnCount = showWeekends ? 7 : 5;

  return (
    <div
      ref={containerRef}
      // Clip, not hide: a hidden box can still be scrolled by script or the
      // browser (e.g. scrollIntoView), shifting the rows. They only move by
      // scrollStyle.
      className={cn("relative h-full overflow-clip", className)}
    >
      <div style={scrollStyle}>
        <div
          className="grid"
          style={{
            gridTemplateRows: `repeat(${weekRows.length}, ${cellHeight || 0}px)`,
          }}
        >
          {weekRows.map((weekRow, rowIndex) => {
            // Rows above and below the screen are scroll buffer: inert, so
            // their events can't be tabbed to or read out
            const isOnScreen =
              rowIndex >= visibleRowStart &&
              rowIndex < visibleRowStart + (visibleRowCount ?? weekRows.length);
            const visibleDays = showWeekends
              ? weekRow.days
              : weekRow.days.filter(
                  (d) => d.date.getDay() !== 0 && d.date.getDay() !== 6,
                );

            const weekNumberCol = showWeekNumbers ? "2rem " : "";
            const dayCols = `repeat(${columnCount}, minmax(0, 1fr))`;
            const gridTemplateColumns = `${weekNumberCol}${dayCols}`;

            return (
              <div
                key={weekRow.days[0].date.toISOString()}
                inert={!isOnScreen}
                className="grid min-h-0"
                style={{ gridTemplateColumns }}
              >
                {showWeekNumbers && (
                  <div className="flex items-start justify-center pt-1.5 text-[10px] text-muted-foreground border-b border-r border-border">
                    {weekRow.weekNumber}
                  </div>
                )}

                {visibleDays.map((day) => {
                  const key = startOfDay(day.date).toISOString();
                  const layout = cellLayouts.get(key);

                  return (
                    <MonthViewDayCell
                      key={key}
                      date={day.date}
                      currentMonth={currentMonth}
                      barSlots={layout?.barSlots ?? []}
                      eventSlots={layout?.eventSlots ?? []}
                      totalEvents={layout?.totalEvents ?? 0}
                      onEventClick={onEventClick}
                      onContextMenu={onContextMenu}
                      onMoreClick={onMoreClick}
                      onDayNumberClick={onDayNumberClick}
                      onBackgroundClick={onBackgroundClick}
                      onDragPointerDown={onDragPointerDown}
                      onResizePointerDown={onResizePointerDown}
                      selectedEventId={selectedEventId}
                      dragEventId={dragEventId}
                      resizeEventId={resizeEventId}
                      dragTargetDate={dragTargetDate}
                      dragEvent={dragEvent}
                      showEventPopover={showEventPopover}
                      onEventChange={onEventChange}
                      onEventPopoverExpand={onEventPopoverExpand}
                      onEventPopoverClose={onEventPopoverClose}
                    />
                  );
                })}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

"use client";

import { useId, useRef } from "react";
import {
  isSameMonth,
  isSameDay,
  format,
  differenceInCalendarDays,
  addDays,
  startOfDay,
} from "date-fns";
import type { Locale } from "date-fns";
import { cn } from "@/lib/utils";
import { useToday } from "@/hooks/use-now";
import type { CalendarEvent, EventColor } from "./calendar-types";
import type { MonthCellSlot } from "@/lib/event-utils";
import {
  formatCellDate,
  formatFullDate,
  isMultiDayEvent,
  resolveEventColor,
} from "@/lib/event-utils";
import { EventDetailPopover } from "./event-detail-popover";
import { getEventDetailsTriggerProps } from "./calendar-event-item";
import { useCalendarConfig } from "./calendar-provider";
import { MonthViewEventItem } from "./month-view-event-item";
import { MonthViewEventBar } from "./month-view-event-bar";

export interface MonthViewDayCellProps {
  date: Date;
  currentMonth: Date;
  barSlots: MonthCellSlot[];
  eventSlots: MonthCellSlot[];
  totalEvents: number;
  onEventClick?: (event: CalendarEvent) => void;
  onContextMenu?: (e: React.MouseEvent, event: CalendarEvent) => void;
  onMoreClick?: (date: Date) => void;
  onDayNumberClick?: (date: Date) => void;
  onBackgroundClick?: () => void;
  onDragPointerDown?: (
    e: React.PointerEvent<HTMLElement>,
    event: CalendarEvent,
  ) => void;
  onResizePointerDown?: (
    e: React.PointerEvent<HTMLElement>,
    event: CalendarEvent,
    edge: "left" | "right",
  ) => void;
  selectedEventId?: string;
  dragEventId?: string;
  /** ID of the event currently being resized (renders as selected) */
  resizeEventId?: string;
  dragTargetDate?: Date;
  dragEvent?: CalendarEvent;
  /** Whether the selected event shows its details popover */
  showEventPopover?: boolean;
  onEventChange?: (event: CalendarEvent) => void;
  /** Callback for the popover's expand button (hidden when absent) */
  onEventPopoverExpand?: () => void;
  /** Callback to close the popover (clears the selection) */
  /** Closes the given event's popover (clears it only while it is still selected) */
  onEventPopoverClose?: (eventId: string) => void;
  className?: string;
}

/** Returns the full month name for first-of-month labels */
function getMonthName(date: Date, locale: Locale): string {
  return format(date, "MMMM", { locale });
}

/** Border color for drag placeholder outline */
const placeholderBorderStyles: Record<EventColor, string> = {
  red: "border-event-red-border",
  orange: "border-event-orange-border",
  yellow: "border-event-yellow-border",
  green: "border-event-green-border",
  blue: "border-event-blue-border",
  purple: "border-event-purple-border",
  gray: "border-event-gray-border",
};

export function MonthViewDayCell({
  date,
  currentMonth,
  barSlots,
  eventSlots,
  onEventClick,
  onContextMenu,
  onMoreClick,
  onDayNumberClick,
  onBackgroundClick,
  onDragPointerDown,
  onResizePointerDown,
  selectedEventId,
  dragEventId,
  resizeEventId,
  dragTargetDate,
  dragEvent,
  showEventPopover,
  onEventChange,
  onEventPopoverExpand,
  onEventPopoverClose,
  className,
}: MonthViewDayCellProps) {
  const dayNumber = date.getDate();
  const { calendars, locale } = useCalendarConfig();
  /** The cell: the selected event's details popover opens beside it */
  const cellRef = useRef<HTMLDivElement>(null);
  /** The selected event's details popover, for its event's `aria-controls` */
  const detailsId = useId();
  // `null` on the server and during hydration, so no cell is marked as today
  const today = useToday();
  const todayDate = today !== null && isSameDay(date, today);
  const isAdjacentMonth = !isSameMonth(date, currentMonth);
  const isWeekend = date.getDay() === 0 || date.getDay() === 6;
  const isFirstOfMonth = dayNumber === 1;

  // Find the selected event in this cell's slots (for cell-level popover).
  // For multi-day bars that span across week rows, only show the popover
  // on the cell matching the event's true start date to avoid duplicates.
  const selectedCellEvent =
    selectedEventId && showEventPopover && !dragEventId && !resizeEventId
      ? (() => {
          for (const slot of barSlots) {
            if (
              slot.type === "event-bar" &&
              slot.isStart &&
              slot.event.id === selectedEventId &&
              isSameDay(startOfDay(slot.event.start), date)
            )
              return slot.event;
          }
          for (const slot of eventSlots) {
            if (slot.type === "event-item" && slot.event.id === selectedEventId)
              return slot.event;
          }
          return null;
        })()
      : null;

  /** ARIA for an event in this cell: the selected one controls the popover */
  const detailsTriggerProps = (eventId: string) =>
    getEventDetailsTriggerProps({
      showEventPopover: showEventPopover ?? false,
      showPopover: selectedCellEvent?.id === eventId,
      detailsId,
    });

  const showPlaceholder =
    dragEventId &&
    dragTargetDate &&
    dragEvent &&
    isSameDay(date, dragTargetDate);
  const placeholderBorder = dragEvent
    ? placeholderBorderStyles[resolveEventColor(dragEvent, calendars)]
    : "border-event-blue-border";

  // Calculate placeholder span for multi-day events
  const isMultiDay = dragEvent
    ? dragEvent.isAllDay || isMultiDayEvent(dragEvent)
    : false;
  const placeholderSpan = dragEvent
    ? isMultiDay
      ? differenceInCalendarDays(
          dragEvent.isAllDay
            ? addDays(startOfDay(dragEvent.end), 1)
            : dragEvent.end,
          dragEvent.start,
        )
      : 1
    : 1;

  function handleBackgroundClick(e: React.MouseEvent) {
    if (
      (e.target as HTMLElement).closest("[role=button]") ||
      (e.target as HTMLElement).closest("button")
    )
      return;
    onBackgroundClick?.();
  }

  /** The cell's day in full ("Tuesday, October 31"), its accessible name */
  const fullDate = formatFullDate(date, locale);

  const cellContent = (
    <div
      ref={cellRef}
      data-date={formatCellDate(date)}
      role="group"
      aria-label={fullDate}
      onClick={handleBackgroundClick}
      className={cn(
        "flex flex-col border-b border-r border-border min-w-0",
        isWeekend && "bg-calendar-weekend",
        className,
      )}
    >
      {/* Day number — right-aligned like Notion Calendar */}
      <div className="flex justify-end items-center px-2 pt-0.5 pb-0.5">
        <button
          type="button"
          aria-label={fullDate}
          onClick={() => onDayNumberClick?.(date)}
          className={cn(
            "flex h-6 min-w-6 items-center justify-center rounded-sm px-1 text-[13px] font-medium leading-none cursor-pointer select-none gap-1",
            todayDate
              ? "bg-primary text-primary-foreground hover:bg-primary/80"
              : cn(
                  "hover:bg-accent",
                  isAdjacentMonth ? "text-muted-foreground" : "text-foreground",
                ),
          )}
        >
          {isFirstOfMonth && (
            <span className="font-semibold">{getMonthName(date, locale)}</span>
          )}
          {dayNumber}
        </button>
      </div>

      {/* Spanning bars + multi-day drag placeholder */}
      {(barSlots.length > 0 || (showPlaceholder && isMultiDay)) && (
        <div className="relative flex flex-col gap-px pb-px">
          {/* Multi-day drag placeholder — absolute overlay */}
          {showPlaceholder && isMultiDay && (
            <div
              aria-hidden
              className={cn(
                "absolute top-0 left-0.5 right-0.5 h-5 rounded-sm border-2 pointer-events-none",
                placeholderBorder,
              )}
              style={{
                width: `calc(${placeholderSpan * 100}% - 4px)`,
                zIndex: 30,
              }}
            />
          )}
          {barSlots.map((slot, index) => {
            if (slot.type === "event-bar") {
              if (slot.isStart) {
                if (slot.colSpan > 1) {
                  const barEl = (
                    <div
                      key={`${slot.event.id}-${index}`}
                      className="relative pl-0.5 pr-0.5"
                      style={{ width: `${slot.colSpan * 100}%`, zIndex: 1 }}
                    >
                      <MonthViewEventBar
                        event={slot.event}
                        colSpan={slot.colSpan}
                        roundedLeft={slot.roundedLeft}
                        roundedRight={slot.roundedRight}
                        isSelected={
                          selectedEventId === slot.event.id ||
                          resizeEventId === slot.event.id
                        }
                        isGhost={dragEventId === slot.event.id}
                        isResizing={resizeEventId === slot.event.id}
                        detailsTriggerProps={detailsTriggerProps(slot.event.id)}
                        onClick={onEventClick}
                        onContextMenu={onContextMenu}
                        onDragPointerDown={onDragPointerDown}
                        onResizePointerDown={onResizePointerDown}
                      />
                    </div>
                  );
                  return barEl;
                }
                return (
                  <div key={`${slot.event.id}-${index}`} className="px-0.5">
                    <MonthViewEventBar
                      event={slot.event}
                      colSpan={slot.colSpan}
                      roundedLeft={slot.roundedLeft}
                      roundedRight={slot.roundedRight}
                      isSelected={selectedEventId === slot.event.id}
                      isResizing={resizeEventId === slot.event.id}
                      detailsTriggerProps={detailsTriggerProps(slot.event.id)}
                      onClick={onEventClick}
                      onContextMenu={onContextMenu}
                      onDragPointerDown={onDragPointerDown}
                      onResizePointerDown={onResizePointerDown}
                    />
                  </div>
                );
              }
              // Continuation cell — invisible placeholder (bar rendered from start cell)
              return (
                <div
                  key={`bar-placeholder-${index}`}
                  className="h-5 shrink-0"
                />
              );
            }

            // spacer — maintains vertical alignment with bars on other days
            return <div key={`spacer-${index}`} className="h-5 shrink-0" />;
          })}
        </div>
      )}

      {/* Timed events — overflow-hidden to clip excess */}
      <div className="relative flex flex-col gap-px px-0.5 pb-0.5 overflow-hidden min-h-0 flex-1">
        {/* Timed event drag placeholder — absolute overlay, doesn't push events */}
        {showPlaceholder && !isMultiDay && (
          <div
            aria-hidden
            className={cn(
              "absolute inset-x-0.5 top-0 h-5 rounded-sm border-2 pointer-events-none z-30",
              placeholderBorder,
            )}
          />
        )}
        {eventSlots.map((slot, index) => {
          if (slot.type === "event-item") {
            const itemEl = (
              <MonthViewEventItem
                key={`${slot.event.id}-${index}`}
                event={slot.event}
                isSelected={selectedEventId === slot.event.id}
                isGhost={dragEventId === slot.event.id}
                detailsTriggerProps={detailsTriggerProps(slot.event.id)}
                onClick={onEventClick}
                onContextMenu={onContextMenu}
                onDragPointerDown={onDragPointerDown}
              />
            );
            return itemEl;
          }

          if (slot.type === "more") {
            return (
              <button
                key={`more-${index}`}
                type="button"
                aria-label={`Show ${slot.count} more ${slot.count === 1 ? "event" : "events"} on ${fullDate}`}
                onClick={() => onMoreClick?.(date)}
                className="px-1 py-0.5 text-xs font-bold text-foreground rounded-sm text-left cursor-default select-none"
              >
                {slot.count} more
              </button>
            );
          }

          return null;
        })}
      </div>
    </div>
  );

  return (
    <>
      {cellContent}
      {selectedCellEvent && (
        <EventDetailPopover
          event={selectedCellEvent}
          id={detailsId}
          anchor={cellRef}
          onEventChange={onEventChange}
          onClose={() => onEventPopoverClose?.(selectedCellEvent.id)}
          onExpand={onEventPopoverExpand}
          side="right"
          align="start"
        />
      )}
    </>
  );
}

"use client";

import { cn } from "@/lib/utils";
import { useIsPast } from "@/hooks/use-now";
import { isPrimaryPress } from "@/hooks/use-pointer-gesture";
import { EventContentSlot, useCalendarConfig } from "./calendar-provider";
import { EVENT_FOCUS_RING_CLASS } from "./calendar-event-item";
import { getEventLabel, resolveEventColor } from "@/lib/event-utils";
import type { CalendarEvent, EventColor } from "./calendar-types";
import type { EventDetailsTriggerProps } from "./week-view-types";

/** Width in pixels of the resize hotzone at each edge */
const RESIZE_HOTZONE_PX = 6;

/**
 * Box for custom `renderEventContent` output: above the background layers,
 * filling the bar (side insets match the default title's)
 */
const MONTH_BAR_SLOT_CLASS =
  "relative flex h-full min-w-0 flex-1 items-center overflow-hidden";

export interface MonthViewEventBarProps {
  event: CalendarEvent;
  colSpan: number;
  roundedLeft: boolean;
  roundedRight: boolean;
  isSelected?: boolean;
  isGhost?: boolean;
  /** Whether this is the copy following the pointer during a drag */
  isDragging?: boolean;
  /** Whether the bar's edges are being dragged (passed to `renderEventContent`) */
  isResizing?: boolean;
  /** ARIA for opening the event's details in a popover */
  detailsTriggerProps?: EventDetailsTriggerProps;
  onClick?: (event: CalendarEvent) => void;
  onContextMenu?: (e: React.MouseEvent, event: CalendarEvent) => void;
  onDragPointerDown?: (
    e: React.PointerEvent<HTMLElement>,
    event: CalendarEvent,
  ) => void;
  onResizePointerDown?: (
    e: React.PointerEvent<HTMLElement>,
    event: CalendarEvent,
    edge: "left" | "right",
  ) => void;
  className?: string;
}

const barColorStyles: Record<
  EventColor,
  { bg: string; bgHover: string; border: string; text: string }
> = {
  red: {
    bg: "bg-event-red-bg",
    bgHover: "hover:bg-event-red-bg/70",
    border: "bg-event-red-border",
    text: "text-event-red",
  },
  orange: {
    bg: "bg-event-orange-bg",
    bgHover: "hover:bg-event-orange-bg/70",
    border: "bg-event-orange-border",
    text: "text-event-orange",
  },
  yellow: {
    bg: "bg-event-yellow-bg",
    bgHover: "hover:bg-event-yellow-bg/70",
    border: "bg-event-yellow-border",
    text: "text-event-yellow",
  },
  green: {
    bg: "bg-event-green-bg",
    bgHover: "hover:bg-event-green-bg/70",
    border: "bg-event-green-border",
    text: "text-event-green",
  },
  blue: {
    bg: "bg-event-blue-bg",
    bgHover: "hover:bg-event-blue-bg/70",
    border: "bg-event-blue-border",
    text: "text-event-blue",
  },
  purple: {
    bg: "bg-event-purple-bg",
    bgHover: "hover:bg-event-purple-bg/70",
    border: "bg-event-purple-border",
    text: "text-event-purple",
  },
  gray: {
    bg: "bg-event-gray-bg",
    bgHover: "hover:bg-event-gray-bg/70",
    border: "bg-event-gray-border",
    text: "text-event-gray",
  },
};

export function MonthViewEventBar({
  event,
  roundedLeft,
  roundedRight,
  isSelected = false,
  isGhost,
  detailsTriggerProps,
  isDragging = false,
  isResizing = false,
  onClick,
  onContextMenu,
  onDragPointerDown,
  onResizePointerDown,
  className,
}: MonthViewEventBarProps) {
  const { calendars, hourCycle, locale } = useCalendarConfig();
  const color = resolveEventColor(event, calendars);
  const styles = barColorStyles[color];
  // `false` on the server and during hydration, so the markup matches
  const eventIsPast = useIsPast(event.end);

  function handleClick(e: React.MouseEvent) {
    e.stopPropagation();
    onClick?.(event);
  }

  function handleContextMenu(e: React.MouseEvent) {
    e.preventDefault();
    e.stopPropagation();
    onContextMenu?.(e, event);
  }

  function handleBarMouseMove(e: React.MouseEvent) {
    if (!onResizePointerDown) return;
    const target = e.currentTarget as HTMLElement;
    const rect = target.getBoundingClientRect();
    const offsetX = e.clientX - rect.left;
    const width = rect.width;

    if (roundedLeft && offsetX <= RESIZE_HOTZONE_PX) {
      target.style.setProperty("--cursor", "col-resize");
      return;
    }
    if (roundedRight && offsetX >= width - RESIZE_HOTZONE_PX) {
      target.style.setProperty("--cursor", "col-resize");
      return;
    }
    target.style.removeProperty("--cursor");
  }

  function handlePointerDown(e: React.PointerEvent<HTMLElement>) {
    if (!isPrimaryPress(e)) return;
    e.stopPropagation();

    if (onResizePointerDown) {
      const rect = e.currentTarget.getBoundingClientRect();
      const offsetX = e.clientX - rect.left;
      const width = rect.width;

      if (roundedLeft && offsetX <= RESIZE_HOTZONE_PX) {
        onResizePointerDown(e, event, "left");
        return;
      }
      if (roundedRight && offsetX >= width - RESIZE_HOTZONE_PX) {
        onResizePointerDown(e, event, "right");
        return;
      }
    }

    onDragPointerDown?.(e, event);
  }

  function handleKeyDown(e: React.KeyboardEvent) {
    if (e.key !== "Enter" && e.key !== " ") return;
    e.preventDefault();
    onClick?.(event);
  }

  return (
    <div
      role="button"
      // Ghosts and the copy following the pointer are drag visuals, not events
      tabIndex={isGhost || isDragging ? -1 : 0}
      aria-hidden={isGhost || isDragging || undefined}
      aria-label={getEventLabel(event, hourCycle, locale)}
      aria-pressed={isSelected}
      {...(!isGhost && !isDragging && detailsTriggerProps)}
      data-event-id={isGhost || isDragging ? undefined : event.id}
      onClick={handleClick}
      onContextMenu={handleContextMenu}
      onPointerDown={handlePointerDown}
      onMouseMove={handleBarMouseMove}
      onKeyDown={handleKeyDown}
      className={cn(
        "relative h-5 flex items-center overflow-hidden",
        "cursor-default select-none",
        "focus:outline-none",
        EVENT_FOCUS_RING_CLASS,
        roundedLeft && "rounded-l-sm",
        roundedRight && "rounded-r-sm",
        isSelected && "z-20",
        eventIsPast && !isGhost && "opacity-50",
        isGhost && "opacity-30 pointer-events-none",
        className,
      )}
    >
      {/* Solid background layer to prevent transparency bleed-through */}
      <div
        className={cn(
          "absolute inset-0 bg-white dark:bg-[#191919]",
          roundedLeft && "rounded-l-sm",
          roundedRight && "rounded-r-sm",
        )}
      />

      {/* Colored background layer - uses border color when selected */}
      <div
        className={cn(
          "absolute inset-0",
          roundedLeft && "rounded-l-sm",
          roundedRight && "rounded-r-sm",
          isSelected ? styles.border : cn(styles.bg, styles.bgHover),
        )}
      />

      {/* Left border accent - only when roundedLeft and not selected */}
      {roundedLeft && !isSelected && (
        <div
          className={cn(
            "absolute left-0 top-0 bottom-0 w-[3px] dark:bg-white dark:mix-blend-overlay",
            "rounded-l-sm",
            styles.border,
          )}
        />
      )}

      {/* Event title */}
      <EventContentSlot
        event={event}
        view="month"
        placement="month-bar"
        isSelected={isSelected}
        isPast={eventIsPast}
        isDragging={isDragging}
        isResizing={isResizing}
        isCompact
        timeLabel=""
        className={cn(
          MONTH_BAR_SLOT_CLASS,
          roundedLeft ? "pl-1.5" : "pl-1",
          roundedRight ? "pr-1" : "pr-0",
        )}
        fallback={
          <span
            className={cn(
              "relative text-[0.6875rem] font-medium leading-tight truncate",
              roundedLeft ? "pl-1.5" : "pl-1",
              roundedRight ? "pr-1" : "pr-0",
              isSelected
                ? "text-white dark:text-white"
                : cn(styles.text, "dark:text-white/80"),
            )}
          >
            {event.title}
          </span>
        }
      />
    </div>
  );
}

