      {...(!isGhost && !isDragging && detailsTriggerProps)}
      data-event-id={isGhost || isDragging ? undefined : event.id}
      onClick={handleClick}
      onContextMenu={handleContextMenu}
      onPointerDown={handlePointerDown}
      onKeyDown={handleKeyDown}
      className={cn(
        "h-5 flex items-center overflow-hidden rounded-sm",
        "cursor-default select-none",
        "hover:bg-accent",
        "focus:outline-none",
        // Positioned only while focused, for the ring overlay
        "focus-visible:relative",
        EVENT_FOCUS_RING_CLASS,
        isSelected && "bg-accent z-20",
        eventIsPast && "opacity-50",
        isGhost && "opacity-30 pointer-events-none",
        className,
      )}
    >
      {/* Colored left border */}
      <div
        className={cn(
          "w-[3px] self-stretch shrink-0 rounded-l-sm",
          borderColor,
        )}
      />

      {/* Time + Title */}
      <EventContentSlot
        event={event}
        view="month"
        placement="month-item"
        isSelected={isSelected}
        isPast={eventIsPast}
        isDragging={isDragging}
        isResizing={false}
        isCompact
        timeLabel={startTimeLabel}
        className={MONTH_ITEM_SLOT_CLASS}
        fallback={
          <span className="text-[0.6875rem] leading-tight truncate pl-1 pr-1">
            <span className={timeColor}>{startTimeLabel}</span>{" "}
            <span className={cn("font-bold", titleColor)}>{event.title}</span>
          </span>
        }
      />
    </div>
  );
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { addDays, differenceInCalendarDays } from "date-fns";

import {
  suppressNextClick,
  usePointerGesture,
} from "@/hooks/use-pointer-gesture";
import { parseCellDate } from "@/lib/event-utils";
import type {
  CalendarEvent,
  PointerGestureStart,
} from "@/components/calendar-types";

/**
 * State of an in-progress month-view event drag operation.
 * Simpler than the week-view drag state — only tracks day-level snapping.
 */
export interface MonthDragState {
  /** ID of the event being dragged */
  eventId: string;
  /** The original event being dragged */
  event: CalendarEvent;
  /** The date under the pointer when the drag began */
  originalDate: Date;
  /** The date the cursor is currently over */
  targetDate: Date;
  /** Whether the drag threshold has been met */
  isDragging: boolean;
  /** Viewport X for fixed-position floating copy */
  clientX: number;
  /** Viewport Y for fixed-position floating copy */
  clientY: number;
}

interface UseMonthEventDragOptions {
  /** Ref to the grid container element (used for hit-testing cells) */
  gridRef: React.RefObject<HTMLDivElement | null>;
  /** Current list of events */
  events: CalendarEvent[];
  /** Called when an event is modified (date shifted) */
  onEventChange?: (event: CalendarEvent) => void;
  /** Called on pointerup to select the event (after the drop, if it moved) */
  onEventClick?: (event: CalendarEvent) => void;
}

interface UseMonthEventDragReturn {
  /** Current drag state, or null when not dragging */
  dragState: MonthDragState | null;
  /** Attach to event elements' onPointerDown */
  handleDragPointerDown: (
    e: React.PointerEvent<HTMLElement>,
    event: CalendarEvent,
  ) => void;
}

/** Minimum pixel distance before a click becomes a drag */
const DRAG_THRESHOLD_PX = 4;

/**
 * Finds the date of the grid cell under the given viewport coordinates.
 * Uses elementsFromPoint so the browser handles CSS transforms
 * (vertical scroll offset, buffered rows) automatically.
 */
function getDateAtPoint(
  gridEl: HTMLElement,
  clientX: number,
  clientY: number,
): Date | null {
  const elements = document.elementsFromPoint(clientX, clientY);
  for (const el of elements) {
    const dateAttr = el.getAttribute("data-date");
    if (dateAttr && gridEl.contains(el)) {
      return parseCellDate(dateAttr);
    }
  }
  return null;
}

interface DragInfo {
  eventId: string;
  event: CalendarEvent;
  /** Pointer driving the drag; moves from other pointers are ignored */
  pointerId: number;
  /** "mouse", "pen" or "touch" */
  pointerType: string;
  originalDate: Date;
  startClientX: number;
  startClientY: number;
  isDragging: boolean;
  /** Latest date under the cursor, committed to the parent on pointerup */
  targetDate: Date;
}

export function useMonthEventDrag({
  gridRef,
  events,
  onEventChange,
  onEventClick,
}: UseMonthEventDragOptions): UseMonthEventDragReturn {
  const [dragState, setDragState] = useState<MonthDragState | null>(null);
  const { startGesture } = usePointerGesture({ containerRef: gridRef });

  const dragRef = useRef<DragInfo | null>(null);
  const onEventChangeRef = useRef(onEventChange);
  const onEventClickRef = useRef(onEventClick);
  const eventsRef = useRef(events);

  useEffect(() => {
    onEventChangeRef.current = onEventChange;
  }, [onEventChange]);
  useEffect(() => {
    onEventClickRef.current = onEventClick;
  }, [onEventClick]);
  useEffect(() => {
    eventsRef.current = events;
  }, [events]);

  // Store handlers in refs to break circular dependency
  const handlePointerMoveRef = useRef<((e: PointerEvent) => void) | null>(null);
  const handlePointerUpRef = useRef<((e: PointerEvent) => void) | null>(null);
  const handlePointerCancelRef = useRef<((e: PointerEvent) => void) | null>(
    null,
  );

  const cleanup = useCallback(() => {
    if (handlePointerMoveRef.current) {
      window.removeEventListener("pointermove", handlePointerMoveRef.current);
    }
    if (handlePointerUpRef.current) {
      window.removeEventListener("pointerup", handlePointerUpRef.current);
    }
    if (handlePointerCancelRef.current) {
      window.removeEventListener(
        "pointercancel",
        handlePointerCancelRef.current,
      );
    }
  }, []);

  // Initialize handlers once (stable references via refs)
  useEffect(() => {
    handlePointerMoveRef.current = (e: PointerEvent) => {
      const drag = dragRef.current;
      if (!drag || e.pointerId !== drag.pointerId) return;

      const deltaX = Math.abs(e.clientX - drag.startClientX);
      const deltaY = Math.abs(e.clientY - drag.startClientY);
      if (
        !drag.isDragging &&
        deltaX < DRAG_THRESHOLD_PX &&
        deltaY < DRAG_THRESHOLD_PX
      )
        return;

      if (!drag.isDragging) {
        drag.isDragging = true;
      }

      const grid = gridRef.current;
      if (!grid) return;

      const targetDate = getDateAtPoint(grid, e.clientX, e.clientY);
      if (!targetDate) return;

      drag.targetDate = targetDate;

      setDragState({
        eventId: drag.eventId,
        event: drag.event,
        originalDate: drag.originalDate,
        targetDate,
        isDragging: true,
        clientX: e.clientX,
        clientY: e.clientY,
      });
    };

    handlePointerUpRef.current = (e: PointerEvent) => {
      const drag = dragRef.current;
      if (!drag || e.pointerId !== drag.pointerId) return;

      cleanup();
      dragRef.current = null;
      setDragState(null);

      // Swallow the click that follows. Without a drag it would select the
      // event a second time; after one it lands on a shared ancestor of the
      // swapped-out item and would clear the selection made below.
      suppressNextClick(drag.pointerType);

      if (!drag.isDragging) {
        // No drag — select the event on pointerup (not pointerdown) so the
        // popover doesn't flash while the user is still holding the mouse.
        onEventClickRef.current?.(drag.event);
        return;
      }

      // Commit from the handler, never from inside a state updater:
      // updaters run during render, and calling the parent's setState
      // there triggers "Cannot update a component while rendering".
      const event = eventsRef.current.find((e) => e.id === drag.eventId);
      if (!event) return;

      const daysDelta = differenceInCalendarDays(
        drag.targetDate,
        drag.originalDate,
      );

      if (daysDelta !== 0) {
        onEventChangeRef.current?.({
          ...event,
          start: addDays(event.start, daysDelta),
          end: addDays(event.end, daysDelta),
        });
      }

      // Select the event after drop so the detail popover opens
      onEventClickRef.current?.(drag.event);
    };

    // The browser took the pointer over (e.g. for a system gesture): drop
    // the drag without committing it
    handlePointerCancelRef.current = (e: PointerEvent) => {
      const drag = dragRef.current;
      if (!drag || e.pointerId !== drag.pointerId) return;

      cleanup();
      dragRef.current = null;
      setDragState(null);
    };
  }, [gridRef, cleanup]);

  const beginDrag = useCallback(
    (
      { clientX, clientY, pointerId, pointerType }: PointerGestureStart,
      event: CalendarEvent,
    ) => {
      // Anchor on the day that was grabbed, not the event's first day: a
      // bar pressed on its third day moves by the cells the pointer crosses
      const grid = gridRef.current;
      const grabbedDate =
        (grid && getDateAtPoint(grid, clientX, clientY)) ?? event.start;

      dragRef.current = {
        eventId: event.id,
        event,
        pointerId,
        pointerType,
        originalDate: grabbedDate,
        startClientX: clientX,
        startClientY: clientY,
        isDragging: false,
        targetDate: grabbedDate,
      };

      setDragState({
        eventId: event.id,
        event,
        originalDate: grabbedDate,
        targetDate: grabbedDate,
        isDragging: false,
        clientX,
        clientY,
      });

      if (handlePointerMoveRef.current) {
        window.addEventListener("pointermove", handlePointerMoveRef.current);
      }
      if (handlePointerUpRef.current) {
        window.addEventListener("pointerup", handlePointerUpRef.current);
      }
      if (handlePointerCancelRef.current) {
        window.addEventListener(
          "pointercancel",
          handlePointerCancelRef.current,
        );
      }
    },
    [gridRef],
  );

  const handleDragPointerDown = useCallback(
    (e: React.PointerEvent<HTMLElement>, event: CalendarEvent) => {
      startGesture(e, (start) => beginDrag(start, event));
    },
    [startGesture, beginDrag],
  );

  // Cleanup on unmount
  useEffect(() => {
    return cleanup;
  }, [cleanup]);

  return { dragState, handleDragPointerDown };
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { startOfDay } from "date-fns";

import {
  isPrimaryPress,
  suppressNextClick,
  usePointerGesture,
} from "@/hooks/use-pointer-gesture";
import { parseCellDate } from "@/lib/event-utils";
import type {
  CalendarEvent,
  PointerGestureStart,
} from "@/components/calendar-types";

/** Minimum cursor movement before entering resize mode */
const DRAG_THRESHOLD_PX = 4;

export interface MonthResizeState {
  eventId: string;
  event: CalendarEvent;
  edge: "left" | "right";
  /** Whether the drag threshold has been met */
  isResizing: boolean;
  /** The new start date during resize */
  currentStart: Date;
  /** The new end date during resize */
  currentEnd: Date;
}

interface ResizeInfo {
  eventId: string;
  event: CalendarEvent;
  /** Pointer driving the resize; moves from other pointers are ignored */
  pointerId: number;
  /** "mouse", "pen" or "touch" */
  pointerType: string;
  edge: "left" | "right";
  startClientX: number;
  isResizing: boolean;
  /** Latest start date, committed to the parent on pointerup */
  currentStart: Date;
  /** Latest end date, committed to the parent on pointerup */
  currentEnd: Date;
}

interface UseMonthEventResizeOptions {
  /** Ref to the grid container (used for hit-testing cells via data-date) */
  gridRef: React.RefObject<HTMLDivElement | null>;
  events: CalendarEvent[];
  onEventChange?: (event: CalendarEvent) => void;
}

interface UseMonthEventResizeReturn {
  resizeState: MonthResizeState | null;
  handleResizePointerDown: (
    e: React.PointerEvent<HTMLElement>,
    event: CalendarEvent,
    edge: "left" | "right",
  ) => void;
}

/**
 * Finds the date of the grid cell under the given viewport coordinates.
 * Uses data-date attributes on day cells via elementFromPoint.
 */
function getDateAtPoint(
  gridEl: HTMLElement,
  clientX: number,
  clientY: number,
): Date | null {
  // Use elementsFromPoint to find the cell under the cursor
  const elements = document.elementsFromPoint(clientX, clientY);
  for (const el of elements) {
    const dateAttr = el.getAttribute("data-date");
    if (dateAttr && gridEl.contains(el)) {
      return parseCellDate(dateAttr);
    }
  }
  return null;
}

export function useMonthEventResize({
  gridRef,
  events,
  onEventChange,
}: UseMonthEventResizeOptions): UseMonthEventResizeReturn {
  const [resizeState, setResizeState] = useState<MonthResizeState | null>(null);
  const { startGesture } = usePointerGesture({ containerRef: gridRef });

  const resizeRef = useRef<ResizeInfo | null>(null);
  const onEventChangeRef = useRef(onEventChange);
  const eventsRef = useRef(events);

  useEffect(() => {
    onEventChangeRef.current = onEventChange;
  }, [onEventChange]);
  useEffect(() => {
    eventsRef.current = events;
  }, [events]);

  const handlePointerMoveRef = useRef<((e: PointerEvent) => void) | null>(null);
  const handlePointerUpRef = useRef<((e: PointerEvent) => void) | null>(null);
  const handlePointerCancelRef = useRef<((e: PointerEvent) => void) | null>(
    null,
  );

  const cleanup = useCallback(() => {
    if (handlePointerMoveRef.current) {
      window.removeEventListener("pointermove", handlePointerMoveRef.current);
    }
    if (handlePointerUpRef.current) {
      window.removeEventListener("pointerup", handlePointerUpRef.current);
    }
    if (handlePointerCancelRef.current) {
      window.removeEventListener(
        "pointercancel",
        handlePointerCancelRef.current,
      );
    }
    document.body.style.removeProperty("--cursor");
  }, []);

  useEffect(() => {
    handlePointerMoveRef.current = (e: PointerEvent) => {
      const resize = resizeRef.current;
      if (!resize || e.pointerId !== resize.pointerId) return;

      const deltaX = Math.abs(e.clientX - resize.startClientX);
      if (!resize.isResizing && deltaX < DRAG_THRESHOLD_PX) return;

      if (!resize.isResizing) {
        resize.isResizing = true;
        document.body.style.setProperty("--cursor", "col-resize");
      }

      const grid = gridRef.current;
      if (!grid) return;

      const targetDate = getDateAtPoint(grid, e.clientX, e.clientY);
      if (!targetDate) return;

      const event = resize.event;
      let newStart = event.start;
      let newEnd = event.end;

      const targetDay = startOfDay(targetDate);

      if (resize.edge === "right") {
        // Right edge: extend/shrink the end. An all-day event's end is its
        // last day (inclusive); a timed event keeps its end's time of day.
        const candidate = event.isAllDay
          ? targetDay
          : new Date(
              targetDay.getTime() +
                (event.end.getTime() - startOfDay(event.end).getTime()),
            );
        // All-day: the last day can't come before the first. Timed: the end
        // must stay after the start.
        const isValid = event.isAllDay
          ? targetDay >= startOfDay(event.start)
          : candidate > event.start;
        if (isValid) newEnd = candidate;
      } else {
        // Left edge: extend/shrink the start, keeping its time of day
        const candidate = new Date(
          targetDay.getTime() +
            (event.start.getTime() - startOfDay(event.start).getTime()),
        );
        const isValid = event.isAllDay
          ? targetDay <= startOfDay(event.end)
          : candidate < event.end;
        if (isValid) newStart = candidate;
      }

      resize.currentStart = newStart;
      resize.currentEnd = newEnd;

      setResizeState({
        eventId: resize.eventId,
        event: resize.event,
        edge: resize.edge,
        isResizing: true,
        currentStart: newStart,
        currentEnd: newEnd,
      });
    };

    handlePointerUpRef.current = (e: PointerEvent) => {
      const resize = resizeRef.current;
      if (!resize || e.pointerId !== resize.pointerId) return;

      cleanup();
      resizeRef.current = null;
      setResizeState(null);

      if (!resize.isResizing) return;
      suppressNextClick(resize.pointerType);

      // Commit from the handler, never from inside a state updater:
      // updaters run during render, and calling the parent's setState
      // there triggers "Cannot update a component while rendering".
      const event = eventsRef.current.find((e) => e.id === resize.eventId);
      if (!event) return;

      onEventChangeRef.current?.({
        ...event,
        start: resize.currentStart,
        end: resize.currentEnd,
      });
    };

    // The browser took the pointer over (e.g. for a system gesture): drop
    // the resize without committing it
    handlePointerCancelRef.current = (e: PointerEvent) => {
      const resize = resizeRef.current;
      if (!resize || e.pointerId !== resize.pointerId) return;

      cleanup();
      resizeRef.current = null;
      setResizeState(null);
    };
  }, [gridRef, cleanup]);

  const beginResize = useCallback(
    (
      { clientX, pointerId, pointerType }: PointerGestureStart,
      event: CalendarEvent,
      edge: "left" | "right",
    ) => {
      resizeRef.current = {
        eventId: event.id,
        event,
        pointerId,
        pointerType,
        edge,
        startClientX: clientX,
        isResizing: false,
        currentStart: event.start,
        currentEnd: event.end,
      };

      setResizeState({
        eventId: event.id,
        event,
        edge,
        isResizing: false,
        currentStart: event.start,
        currentEnd: event.end,
      });

      if (handlePointerMoveRef.current) {
        window.addEventListener("pointermove", handlePointerMoveRef.current);
      }
      if (handlePointerUpRef.current) {
        window.addEventListener("pointerup", handlePointerUpRef.current);
      }
      if (handlePointerCancelRef.current) {
        window.addEventListener(
          "pointercancel",
          handlePointerCancelRef.current,
        );
      }
    },
    [],
  );

  const handleResizePointerDown = useCallback(
    (
      e: React.PointerEvent<HTMLElement>,
      event: CalendarEvent,
      edge: "left" | "right",
    ) => {
      if (!isPrimaryPress(e)) return;
      e.stopPropagation();
      startGesture(e, (start) => beginResize(start, event, edge));
    },
    [startGesture, beginResize],
  );

  useEffect(() => {
    return cleanup;
  }, [cleanup]);

  return { resizeState, handleResizePointerDown };
}

import * as React from "react";

/** Matches when the viewer asked the system to minimize animation */
const REDUCED_MOTION_QUERY = "(prefers-reduced-motion: reduce)";

function getServerSnapshot(): boolean {
  return false;
}

/**
 * Subscribes to a CSS media query and returns whether it currently matches.
 *
 * Returns `false` during server rendering and hydration, then the live value.
 */
export function useMediaQuery(query: string): boolean {
  const subscribe = React.useCallback(
    (onChange: () => void) => {
      const mql = window.matchMedia(query);
      mql.addEventListener("change", onChange);
      return () => mql.removeEventListener("change", onChange);
    },
    [query],
  );

  const getSnapshot = React.useCallback(
    () => window.matchMedia(query).matches,
    [query],
  );

  return React.useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

/**
 * Whether the viewer prefers reduced motion. `false` during server
 * rendering and hydration, then the live value.
 */
export function usePrefersReducedMotion(): boolean {
  return useMediaQuery(REDUCED_MOTION_QUERY);
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { usePrefersReducedMotion } from "@/hooks/use-media-query";

interface UseVerticalScrollOptions {
  /** Ref to the scrollable container element */
  containerRef: React.RefObject<HTMLDivElement | null>;
  /** Height of a single row in pixels */
  rowHeight: number;
  /** Called when scroll settles — receives the number of rows scrolled */
  onNavigate: (rowsDelta: number) => void;
  /** Disable scroll handling (e.g., during drag) */
  disabled?: boolean;
}

interface UseVerticalScrollReturn {
  /** Current scroll offset in pixels (for translateY) */
  scrollOffset: number;
  /** Slide animation offset in pixels (for button/keyboard nav) */
  slideOffset: number;
  /** Whether the user is actively scrolling */
  isScrolling: boolean;
  /** Whether a snap/slide animation is in progress */
  isAnimating: boolean;
  /** Trigger a slide animation for programmatic navigation */
  triggerSlideAnimation: (rowsDelta: number) => void;
}

/** Debounce time after last wheel event before snapping */
const SCROLL_END_DEBOUNCE_MS = 150;

/** Duration of snap/slide CSS transition */
const SNAP_ANIMATION_MS = 200;

export function useVerticalScroll({
  containerRef,
  rowHeight,
  onNavigate,
  disabled,
}: UseVerticalScrollOptions): UseVerticalScrollReturn {
  const [scrollOffset, setScrollOffset] = useState(0);
  const [slideOffset, setSlideOffset] = useState(0);
  const [isScrolling, setIsScrolling] = useState(false);
  const [isAnimating, setIsAnimating] = useState(false);
  // Snaps and slides jump straight to their end instead of animating
  const prefersReducedMotion = usePrefersReducedMotion();

  const scrollEndTimer = useRef<ReturnType<typeof setTimeout>>(null);
  const accumulatedDelta = useRef(0);
  const onNavigateRef = useRef(onNavigate);
  useEffect(() => {
    onNavigateRef.current = onNavigate;
  }, [onNavigate]);

  const snapAndNavigate = useCallback(
    (offset: number) => {
      if (rowHeight <= 0) return;

      const rowsDelta = Math.round(offset / rowHeight);

      if (prefersReducedMotion) {
        if (rowsDelta !== 0) onNavigateRef.current(-rowsDelta);
        setScrollOffset(0);
        setIsScrolling(false);
        accumulatedDelta.current = 0;
        return;
      }

      // If scroll distance < half a row, snap back
      if (rowsDelta === 0) {
        setIsAnimating(true);
        setScrollOffset(0);
        setTimeout(() => {
          setIsAnimating(false);
          setIsScrolling(false);
        }, SNAP_ANIMATION_MS);
        return;
      }

      // Snap to exact row boundary then navigate
      const targetOffset = rowsDelta * rowHeight;
      setIsAnimating(true);
      setScrollOffset(targetOffset);

      setTimeout(() => {
        onNavigateRef.current(-rowsDelta);
        setScrollOffset(0);
        setIsAnimating(false);
        setIsScrolling(false);
        accumulatedDelta.current = 0;
      }, SNAP_ANIMATION_MS);
    },
    [rowHeight, prefersReducedMotion],
  );

  // Programmatic slide animation for button/keyboard navigation
  const triggerSlideAnimation = useCallback(
    (rowsDelta: number) => {
      if (rowHeight <= 0 || isAnimating || isScrolling) return;
      if (prefersReducedMotion) return;

      const startOffset = rowsDelta * rowHeight;
      setSlideOffset(startOffset);

      requestAnimationFrame(() => {
        requestAnimationFrame(() => {
          setIsAnimating(true);
          setSlideOffset(0);
          setTimeout(() => {
            setIsAnimating(false);
          }, SNAP_ANIMATION_MS);
        });
      });
    },
    [rowHeight, isAnimating, isScrolling, prefersReducedMotion],
  );

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const handleWheel = (e: WheelEvent) => {
      if (disabled) return;

      // Only handle vertical-dominant scrolls
      if (Math.abs(e.deltaY) <= Math.abs(e.deltaX)) return;

      e.preventDefault();

      setIsScrolling(true);

      // Negate deltaY: scroll down (positive deltaY) = move calendar up = navigate forward
      accumulatedDelta.current += -e.deltaY;
      setScrollOffset(accumulatedDelta.current);

      // Reset debounce timer
      if (scrollEndTimer.current) {
        clearTimeout(scrollEndTimer.current);
      }

      scrollEndTimer.current = setTimeout(() => {
        snapAndNavigate(accumulatedDelta.current);
        accumulatedDelta.current = 0;
      }, SCROLL_END_DEBOUNCE_MS);
    };

    container.addEventListener("wheel", handleWheel, { passive: false });

    return () => {
      container.removeEventListener("wheel", handleWheel);
      if (scrollEndTimer.current) {
        clearTimeout(scrollEndTimer.current);
      }
    };
  }, [containerRef, snapAndNavigate, disabled]);

  return {
    scrollOffset,
    slideOffset,
    isScrolling,
    isAnimating,
    triggerSlideAnimation,
  };
}
